'use strict';
(()=>{
let gist='',token='',revision='',owner='',ready=false,busy=false,dirty=false,loading=false,conflict=false,timer;
const status=text=>$('#cloudStatus').textContent=text;
const version=g=>g.history?.[0]?.version||g.updated_at;
const draftKey=()=>`mark-ege-draft-${gist}`;
function controls(){const locked=!!gist&&(!ready||!token||busy||loading||conflict);document.querySelectorAll('#addTask,#addExam,[data-edit],[data-exam],[data-done],[data-time],[data-roadmap-write]').forEach(e=>e.disabled=locked);document.querySelectorAll('#prev,#next,#today').forEach(e=>e.disabled=busy||loading);$('#refreshCloud').hidden=!gist;$('#shareCloud').hidden=!gist;$('#setupCloud').textContent=gist?'Доступ Марка':'Подключить Gist';$('#storage').textContent=gist?(dirty?'Есть несохранённые изменения':ready?'Общий прогресс · Gist':'Подключение к Gist'):'Сохранение на этом устройстве'}
async function request(path,method='GET',body){let r=await fetch('https://api.github.com'+path,{method,cache:'no-store',headers:{Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28',...(token?{Authorization:`Bearer ${token}`}:{})},...(body?{body:JSON.stringify(body)}:{})});if(!r.ok)throw Error(r.status===401?'Токен недействителен.':r.status===403?'GitHub ограничил запрос или токен не имеет нужных прав.':r.status===404?'Gist не найден или недоступен.':`Ошибка GitHub (${r.status}).`);return r.json()}
function decode(g){let f=g.files?.['mark-progress.json'];if(!f||f.truncated)throw Error('Нужен полный файл mark-progress.json в Gist.');let s;try{s=JSON.parse(f.content)}catch{throw Error('Файл прогресса повреждён.')}if(!s||!Array.isArray(s.tasks)||!Array.isArray(s.exams)||!Array.isArray(s.weeks))throw Error('Неверный формат прогресса.');let validDate=d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&iso(parse(d))===d;let validId=id=>typeof id==='string'&&/^[a-zA-Z0-9.-]{1,100}$/.test(id);if(!s.weeks.every(validDate)||!s.tasks.every(t=>validId(t.id)&&validDate(t.date)&&Object.hasOwn(names,t.subject)&&typeof t.title==='string'&&t.title.length<=160&&Number.isInteger(t.minutes)&&t.minutes>0&&t.minutes<=1440&&Number.isInteger(t.actual)&&t.actual>=0&&t.actual<=1440&&typeof t.done==='boolean'&&typeof t.teacher==='boolean')||!s.exams.every(e=>validId(e.id)&&validDate(e.date)&&Object.hasOwn(names,e.subject)&&Number.isInteger(e.score)&&e.score>=0&&e.score<=100))throw Error('В Gist есть некорректные записи.');if(window.validateStrategy&&!window.validateStrategy(s.strategy))throw Error('Некорректные данные целей.');return s}
async function refresh(force=false){if(!gist||busy||loading||dirty&&!force)return;loading=true;controls();try{let g=await request('/gists/'+gist);let next=decode(g);revision=version(g);owner=g.owner.login;state=next;ready=true;conflict=false;status('Просмотр · обновлено '+new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})+(token?' · редактирование включено':''));render()}catch(e){status(e.message+' Нажми «Обновить», чтобы повторить.')}finally{loading=false;controls()}}
async function flush(){if(!dirty||busy||!ready||!token||conflict)return;busy=true;controls();let snapshot=JSON.stringify(state);try{let latest=await request('/gists/'+gist);if(version(latest)!==revision){conflict=true;throw Error('Прогресс изменён на другом устройстве. Нажми «Обновить», чтобы загрузить его. Локальный черновик сохранён.')}let g=await request('/gists/'+gist,'PATCH',{files:{'mark-progress.json':{content:snapshot}}});revision=version(g);dirty=false;try{localStorage.removeItem(draftKey())}catch{}status('Сохранено в Gist · '+new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}))}catch(e){status(e.message+' Изменения ещё не отправлены.');}finally{busy=false;controls()}}
window.markCloud={get active(){return !!gist},get writable(){return ready&&!!token&&!conflict},controls,save(){if(!this.writable)return;dirty=true;try{localStorage.setItem(draftKey(),JSON.stringify({revision,state}))}catch{}status('Сохраняем изменения…');clearTimeout(timer);timer=setTimeout(flush,500);controls()}};
$('#setupCloud').onclick=()=>{$('#cloudForm').hidden=!$('#cloudForm').hidden;$('#gistId').value=gist};
$('#cloudForm').onsubmit=async e=>{e.preventDefault();if(dirty){toast('Сначала сохрани или обнови текущий прогресс.');return}let raw=$('#gistId').value.trim(),match=raw.match(/(?:^|\/)([a-f0-9]{20,40})\/?$/i);if(!match){toast('Вставь корректную ссылку или ID Gist.');return}gist=match[1];token=$('#gistToken').value.trim();$('#gistToken').value='';ready=false;controls();status('Подключаем…');try{let g=await request('/gists/'+gist);decode(g);if(token){let u=await request('/user');if(u.login!==g.owner.login)throw Error('Для записи нужен токен владельца этого Gist: '+g.owner.login)}history.replaceState(null,'','#gist='+gist);await refresh(true);if(ready){$('#cloudForm').hidden=true;let draft;try{draft=JSON.parse(localStorage.getItem(draftKey()))}catch{}if(token&&draft){if(draft.revision===revision&&confirm('На этом устройстве есть неотправленные изменения. Восстановить их?')){state=decode({files:{'mark-progress.json':{content:JSON.stringify(draft.state)}}});render();window.markCloud.save()}else status('Подключено. Локальный черновик сохранён отдельно и не заменил данные Gist.')}}}catch(err){token='';ready=false;status(err.message)}controls()};
$('#refreshCloud').onclick=async()=>{if(busy)return;if(dirty&&!conflict){await flush();return}if(dirty&&!confirm('Загрузить общий прогресс вместо текущих изменений? Их черновик останется в этом браузере.'))return;dirty=false;await refresh(true)};
$('#shareCloud').onclick=async()=>{let link=location.origin+location.pathname+'#gist='+gist;try{await navigator.clipboard.writeText(link);toast('Ссылка для просмотра скопирована')}catch{prompt('Скопируй ссылку для просмотра:',link)}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
setInterval(()=>{if(document.visibilityState==='visible'&&!dirty)refresh()},120000);
const params=new URLSearchParams(location.hash.slice(1)),id=params.get('gist');if(id&&/^[a-f0-9]{20,40}$/i.test(id)){gist=id;controls();refresh()}else controls();
})();
